import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.DzNHXt93.js";const m=JSON.parse('{"title":"WorkerCronTrigger — takoform_worker_cron_trigger","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-cron-trigger.md","filePath":"proposals/edge/worker-cron-trigger.md"}'),i={name:"proposals/edge/worker-cron-trigger.md"};function n(d,e,s,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="workercrontrigger-—-takoform-worker-cron-trigger" tabindex="-1">WorkerCronTrigger — <code>takoform_worker_cron_trigger</code> <a class="header-anchor" href="#workercrontrigger-—-takoform-worker-cron-trigger" aria-label="Permalink to &quot;WorkerCronTrigger — `takoform_worker_cron_trigger`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team runs periodic work — cache refresh, cleanup, digests — by having the platform invoke its worker&#39;s <code>scheduled</code> handler on a cron schedule.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. The trigger activates the worker from the outside; deleting the trigger never deletes the worker.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>cron</code> is the portable five-field cron grammar, interpreted in UTC only. There is no timezone field, so two conforming hosts can never fire the same trigger at different instants and no schedule skips or repeats an hour for a daylight-saving transition. Each match invokes the scheduled handler of the worker&#39;s active deployment.</p><p>The five fields are minute <code>0</code>-<code>59</code>, hour <code>0</code>-<code>23</code>, day-of-month <code>1</code>-<code>31</code>, month <code>1</code>-<code>12</code>, and day-of-week <code>0</code>-<code>6</code> with <code>0</code> Sunday. Each field is a comma-separated list of <code>*</code>, a literal, a range <code>low-high</code>, <code>*/step</code>, or <code>low-high/step</code>, so <code>* * * * *</code>, <code>0 * * * *</code>, and <code>*/5 * * * *</code> are all valid — the grammar exists for exactly those. Month and day names, and a step on a bare literal such as <code>5/10</code>, are not accepted. When day-of-month and day-of-week are both restricted the trigger fires on a day either selects; when only one is restricted, only that one constrains the day.</p><p>The pattern in the Form Definition is the structural half of the grammar. A host also PARSES the expression, and refuses a value outside its field&#39;s range, an inverted range, or a step outside <code>1</code>..span, before any mutation; the provider runs the same parser at plan time, so a configuration that plans is one that applies (decision 0020).</p><p>Delivery of a match is at-least-once, so a handler may run more than once for one matched minute and must be idempotent. A missed run is skipped rather than queued or fired late, so a schedule never produces a backlog. An uncaught exception in the handler is a failed invocation reported to host diagnostics; it is not retried within the matched minute.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Schedule plus target is one observable fact. The UTC-only rule is the completeness boundary of decision 0008: leaving the zone open would let two hosts fire at observably different times.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Timezone-aware or calendar-aware scheduling (a <code>TimezoneSchedule</code>) carries different firing semantics and is separate family work.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Attaching a trigger to a worker whose versions do not declare the <code>scheduled</code> handler must fail closed. Updating <code>cron</code> is an in-place update; changing <code>worker</code> replaces the attachment.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The cron trigger of a proven edge platform, restricted to the interoperable five-field UTC grammar: <code>*</code>, literals, lists, ranges, and steps, with no names and no seconds field.</p>',22)])])}const f=r(i,[["render",n]]);export{m as __pageData,f as default};
